function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 100000) return 's needs 3 to 10^5 characters.';
  if (!/^[0-9]+$/.test(s)) return 's may contain only the digits 0 to 9.';
  return null;
}

