function hasSameDigits(s) {
  let digits = s.split('').map(Number);
  while (digits.length > 2) {
    const next = [];
    for (let i = 0; i + 1 < digits.length; i++) next.push((digits[i] + digits[i + 1]) % 10);
    digits = next;
  }
  return digits[0] === digits[1];
}

