function generate(rand, size) {
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 3 + Math.floor(rand() * 10);
  const digits = Array.from({ length: n }, () => Math.floor(rand() * 10));
  const shape = rand();
  if (shape < 0.08) {
    digits.fill(digits[0]);
  } else if (shape < 0.2) {
    for (let i = 0; i < n / 2; i++) digits[n - 1 - i] = digits[i];
  } else if (shape < 0.55) {
    // Pick the last digit so the two final digits match. Their difference is the sum of
    // C(m, i) * (digits[i] - digits[i + 1]) mod 10 with m = n - 2, and the last digit has weight -1.
    // C(m, i) mod 10 is built from C(m, i - 1) * (m - i + 1) / i, keeping the factors 2 and 5 apart.
    const m = n - 2, inverse = [0, 1, 0, 7, 0, 0, 0, 3, 0, 9];
    let twos = 0, fives = 0, rest = 1, gap = 0;
    for (let i = 0; i <= m; i++) {
      if (i > 0) {
        let up = m - i + 1, down = i;
        while (up % 2 === 0) { up /= 2; twos++; }
        while (up % 5 === 0) { up /= 5; fives++; }
        while (down % 2 === 0) { down /= 2; twos--; }
        while (down % 5 === 0) { down /= 5; fives--; }
        rest = rest * (up % 10) * inverse[down % 10] % 10;
      }
      const weight = twos > 0 && fives > 0 ? 0 : rest * (twos > 0 ? [6, 2, 4, 8][twos % 4] : 1) * (fives > 0 ? 5 : 1) % 10;
      gap = (gap + weight * (i < m ? digits[i] - digits[i + 1] : digits[i])) % 10;
    }
    digits[n - 1] = (gap + 10) % 10;
  }
  return [digits.join('')];
}
